def feature(domain, links, assigned_links, basins, basin_open, basin_rest, wipeouts, census_left, depth):
    """1.0 for a singleton domain, 0.5 for a two-value domain, 0.0 otherwise."""
    size = domain.sum(axis=1)
    return np.where(size == 1, 1.0, np.where(size == 2, 0.5, 0.0))

