import numpy as np

def feature(domain, links, assigned_links, basins, basin_open, basin_rest, wipeouts, census_left, depth):
    """Normalised wipeout count per candidate, gated to the late search (more than half the pools assigned)."""
    k = wipeouts.shape[0]
    n = k + depth
    g = 1.0 if k < 0.5 * n else 0.0
    wmax = float(np.max(wipeouts)) if k > 0 else 0.0
    if wmax <= 0.0 or g == 0.0:
        return np.zeros(k)
    return (wipeouts.astype(np.float64) / wmax) * g
